#include "Monstey_LtaReference.hpp"
#include "Monstey_LtaDependency.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <string>
namespace {std::uint64_t Monstey_Cases=0,Monstey_Checks=0,Monstey_BudgetCases=0;void Monstey_Need(bool x,const char*m){++Monstey_Checks;if(!x)throw std::runtime_error(m);}std::uint32_t Monstey_Seed=0xC01671;std::uint32_t Monstey_Random(){Monstey_Seed^=Monstey_Seed<<13;Monstey_Seed^=Monstey_Seed>>17;Monstey_Seed^=Monstey_Seed<<5;return Monstey_Seed;}
void Monstey_Compare(std::span<const std::uint8_t>x){auto e=Monstey_LtaReference::Decode(x);auto a=Monstey::Monstey_ObserveLtaCompressed(x);const char*status[]={"end_marker","truncated_header","unsupported_nonzero_header","missing_end_marker","truncated_literal","truncated_span_index","truncated_span_length","unavailable_initial_window"};Monstey_Need(a.status==status[e.kind],"diagnostic status");Monstey_Need(a.decoded==e.bytes,"all output bytes");Monstey_Need(a.consumed_bits==e.bits,"consumed bits");Monstey_Need(a.literals==e.literals,"literal count");Monstey_Need(a.spans==e.spans&&a.span_bytes==e.span_bytes,"span count and bytes");Monstey_Need(a.unavailable_window_index==e.unknown,"unknown window position");++Monstey_Cases;}
void Monstey_Matrix(){using namespace Monstey_LtaReference;
 for(unsigned c=0;c<256;++c)for(unsigned n=0;n<32;++n){Builder b;for(unsigned j=0;j<n;++j)b.Literal(static_cast<std::uint8_t>(c+j));b.End();Monstey_Compare(b.data);}
 for(unsigned seeds:{1u,2u,15u,16u,255u,4094u,4095u,4096u,4100u})for(unsigned length=2;length<=17;++length)for(unsigned from:{1u,2u,15u,255u,4094u,4095u}){Builder b;for(unsigned j=0;j<seeds;++j)b.Literal(static_cast<std::uint8_t>(j*7u));b.Span(from,length);b.End();Monstey_Compare(b.data);}
 for(unsigned i=0;i<128;++i){Builder b;for(unsigned j=0;j<4096;++j)b.Literal(static_cast<std::uint8_t>(Monstey_Random()));for(unsigned j=0;j<300;++j){if(Monstey_Random()%3)b.Span(1u+Monstey_Random()%4095u,2u+Monstey_Random()%16u);else b.Literal(static_cast<std::uint8_t>(Monstey_Random()));}b.End();Monstey_Compare(b.data);b.data.push_back(0xFF);b.data.push_back(0);Monstey_Compare(b.data);}
 for(unsigned i=0;i<8192;++i){std::vector<std::uint8_t>x(Monstey_Random()%80);for(auto&v:x)v=static_cast<std::uint8_t>(Monstey_Random());if(i%5)for(std::size_t j=0;j<std::min<std::size_t>(4,x.size());++j)x[j]=0;Monstey_Compare(x);}
 {Builder b;b.Literal(0xC7);b.Span(1,17);b.Literal(0xA5);b.End();for(std::size_t n=0;n<=b.data.size();++n)Monstey_Compare(std::span(b.data).first(n));for(unsigned bit=0;bit<32;++bit){auto x=b.data;x[bit/8]|=static_cast<std::uint8_t>(1u<<(bit%8));Monstey_Compare(x);}}
 for(unsigned prefix=0;prefix<20;++prefix){Builder b;for(unsigned n=0;n<prefix;++n)b.Literal(static_cast<std::uint8_t>(n*19));if(prefix)b.Span(1,17);b.End();const auto e=Decode(b.data);for(unsigned budget=0;budget<40;++budget){const auto a=Monstey::Monstey_ObserveLtaCompressed(b.data,budget);const auto size=std::min<std::size_t>(budget,e.bytes.size());Monstey_Need(a.decoded.size()==size&&std::equal(a.decoded.begin(),a.decoded.end(),e.bytes.begin()),"budget exact output prefix");Monstey_Need(a.status==(budget<e.bytes.size()?"output_budget_exhausted":"end_marker"),"budget status");Monstey_Need(a.consumed_bits<=e.bits,"budget does not overconsume");++Monstey_Cases;++Monstey_BudgetCases;}}
}
}
int main(int argc,char**argv){try{if(argc!=2&&argc!=3)throw std::runtime_error("New report and optional actual input");if(std::filesystem::exists(argv[1]))throw std::runtime_error("Report exists");Monstey_Matrix();std::uint64_t actual_bytes=0,actual_bits=0,actual_decoded=0;if(argc==3){std::ifstream f(argv[2],std::ios::binary);if(!f)throw std::runtime_error("Input open");std::vector<std::uint8_t>x((std::istreambuf_iterator<char>(f)),{});Monstey_Compare(x);const auto e=Monstey_LtaReference::Decode(x);Monstey_Need(e.kind==0,"Actual complete marker");actual_bytes=x.size();actual_bits=e.bits;actual_decoded=e.bytes.size();}std::ofstream f(argv[1]);f<<"{\"status\":\"PASS\",\"cases\":"<<Monstey_Cases<<",\"checks\":"<<Monstey_Checks<<",\"budget_cases\":"<<Monstey_BudgetCases<<",\"actual_input_bytes\":"<<actual_bytes<<",\"actual_consumed_bits\":"<<actual_bits<<",\"actual_decoded_bytes\":"<<actual_decoded<<",\"original_instruction_bytes_interpreted\":false,\"native_original_entrypoint_invoked\":false}\n";std::cout<<"PASS "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
